#!/bin/sh
# Runs teleproxy with the command line generated by the gateway in /etc/teleproxy/args
# (users = MTPROXY_USERS, set once for all MTProxy implementations). Listens on 127.0.0.1 only;
# the gateway forwards authenticated Telegram clients from the public port (TELEPROXY_PORT)
# with a PROXY v2 header. Restarts teleproxy whenever the gateway rewrites the args.
DIR=/etc/teleproxy
CONF=$DIR/args

if [ "$1" = run ]; then
  # fake-TLS domains -> 127.0.0.1: teleproxy reads their TLS fingerprint from the gateway itself
  if [ -f "$DIR/hosts" ]; then
    grep -v "# securegate" /etc/hosts > /tmp/hosts.base || true
    { cat /tmp/hosts.base; while read -r h; do [ -n "$h" ] && echo "127.0.0.1 $h # securegate"; done < "$DIR/hosts"; } > /etc/hosts
  fi
  # with an ad tag (MTPROXY_AD_TAG) teleproxy uses Telegram's middle proxies: fetch their config
  if grep -qx -- "-P" "$CONF"; then
    curl -fsSL --retry 3 -o "$DIR/proxy-secret" https://core.telegram.org/getProxySecret || true
    curl -fsSL --retry 3 -o "$DIR/proxy-multi.conf" https://core.telegram.org/getProxyConfig || true
  fi
  # args: one per line (secrets / domains contain no spaces)
  set -f
  IFS='
'
  # shellcheck disable=SC2046
  exec teleproxy $(cat "$CONF")
fi

NAME=teleproxy
. /opt/sg-run.sh
run_supervised /entrypoint.sh run
